// CPU throughput index — record JAH-GPCS-CPU-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"cores": 16, "clock_ghz": 5.4, "tdp_w": 170};
var value = (m.cores*m.clock_ghz*120/Math.sqrt(m.tdp_w));
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-CPU-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-CPU-000001|' + value.toFixed(2) + ' throughput index');

